FMT_BEGIN_NAMESPACE

namespace detail {

template <typename Char, typename PathChar> auto get_path_string(
  const std::filesystem::path& p, const std::basic_string<PathChar>& native) {
  if constexpr (std::is_same_v<Char, char> && std::is_same_v<PathChar, wchar_t>)
    return to_utf8<wchar_t>(native, to_utf8_error_policy::replace);
  else
    return p.string<Char>();
}

template <typename Char, typename PathChar>
void write_escaped_path(basic_memory_buffer<Char>& quoted,
                        const std::filesystem::path& p,
                        const std::basic_string<PathChar>& native) {
  if constexpr (std::is_same_v<Char, char> && std::is_same_v<PathChar, wchar_t>) {
    auto buf = basic_memory_buffer<wchar_t>();
    write_escaped_string<wchar_t>(std::back_inserter(buf), native);
    bool valid = to_utf8<wchar_t>::convert(quoted, {buf.data(), buf.size()});
    FMT_ASSERT(valid, "invalid utf16");
  } else if constexpr (std::is_same_v<Char, PathChar>) {
    write_escaped_string<std::filesystem::path::value_type>(
        std::back_inserter(quoted), native);
  } else {
    write_escaped_string<Char>(std::back_inserter(quoted), p.string<Char>());
  }
}

}  // namespace detail

FMT_EXPORT
template <typename Char> struct formatter<std::filesystem::path, Char> {
 private:
  format_specs<Char> specs_;
  detail::arg_ref<Char> width_ref_;
  bool debug_ = false;

 public:
  FMT_CONSTEXPR void set_debug_format(bool set = true) { debug_ = set; }

  template <typename ParseContext> FMT_CONSTEXPR auto parse(ParseContext& ctx) {
    auto it = ctx.begin(), end = ctx.end();
    if (it == end) return it;

    it = detail::parse_align(it, end, specs_);
    if (it == end) return it;

    it = detail::parse_dynamic_spec(it, end, specs_.width, width_ref_, ctx);
    if (it != end && *it == '?') {
      debug_ = true;
      ++it;
    }
    return it;
  }

  template <typename FormatContext>
  auto format(const std::filesystem::path& p, FormatContext& ctx) const {
    auto specs = specs_;
    auto path_string = p.native();
    switch (width_ref_.kind) {
    case detail::arg_id_kind::none:
      break;
    case detail::arg_id_kind::index: {
      auto width_arg = ctx.arg(width_ref_.val.index);
      if (!width_arg) ctx.on_error("argument not found");
      specs.width = detail::get_dynamic_spec<detail::width_checker>(
          width_arg, ctx.error_handler());
      break;
    }
    case detail::arg_id_kind::name: {
      auto width_arg = ctx.arg(width_ref_.val.name);
      if (!width_arg) ctx.on_error("argument not found");
      specs.width = detail::get_dynamic_spec<detail::width_checker>(
          width_arg, ctx.error_handler());
      break;
    }
    }
    using path_char = typename std::filesystem::path::value_type;
    if (!debug_) {
      if constexpr (std::is_same_v<Char, path_char>) {
        auto converted = p.string<Char>();
        auto view = basic_string_view<Char>(converted);
        auto data = view.data();
        auto size = view.size();
        if (specs.precision >= 0 &&
            detail::to_unsigned(specs.precision) < size) {
          size = detail::code_point_index(
              view, detail::to_unsigned(specs.precision));
        }
        bool is_debug = specs.type == presentation_type::debug;
        size_t display_width = 0;
        if (specs.width != 0) {
          if (is_debug) {
            display_width =
                detail::write_escaped_string(detail::counting_iterator{}, view)
                    .count();
          } else {
            display_width =
                detail::compute_width(basic_string_view<Char>(data, size));
          }
        }
        return detail::write_padded(
            ctx.out(), specs, size, display_width,
            [=](detail::reserve_iterator<decltype(ctx.out())> it) {
              if (is_debug) return detail::write_escaped_string(it, view);
              return detail::copy_str<Char>(data, data + size, it);
            });
      } else {
        auto s = detail::get_path_string<Char>(p, path_string);
        return detail::write(ctx.out(), basic_string_view<Char>(s), specs);
      }
    }
    auto quoted = basic_memory_buffer<Char>();
    if constexpr (std::is_same_v<Char, path_char>) {
      auto out = std::back_inserter(quoted);
      const auto* begin = path_string.data();
      const auto* end = begin + path_string.size();
      *out++ = static_cast<Char>('"');
      do {
        auto escape = detail::find_escape(begin, end);
        for (auto it = begin; it != escape.begin; ++it) {
          *out++ = static_cast<Char>(*it);
        }
        begin = escape.end;
        if (!begin) {
          break;
        }
        out = detail::write_escaped_cp(out, escape);
      } while (begin != end);
      *out++ = static_cast<Char>('"');
    } else {
      detail::write_escaped_path(quoted, p, path_string);
    }
    return detail::write(ctx.out(),
                         basic_string_view<Char>(quoted.data(), quoted.size()),
                         specs);
  }
};
FMT_END_NAMESPACE
#endif // FMT_CPP_LIB_FILESYSTEM

